const {chromium}=require('C:/Users/ASUS/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const fs=require('fs'),path=require('path'),{spawn}=require('child_process');
const run=process.argv[2]||'baseline-workbench',source=path.resolve(process.argv[3]||'work/source-baseline'),out=path.resolve('outputs/求职工作台独立验收/runs',run);fs.mkdirSync(out,{recursive:true});
const results=[],requests=[];let browser,server,page;const save=(name,data)=>fs.writeFileSync(path.join(out,name),typeof data==='string'?data:JSON.stringify(data,null,2));
function check(id,passed,detail={}){results.push({id,status:passed?'PASS':'FAIL',...detail});console.log(JSON.stringify(results.at(-1)));}
async function screenshot(name){await page.screenshot({path:path.join(out,name+'.png'),fullPage:true});save(name+'.txt',await page.locator('body').innerText());}
(async()=>{let fatal=null;try{
server=spawn(process.execPath,[path.join(source,'scripts/serve.mjs')],{cwd:source,windowsHide:true,env:{...process.env,JOB_WORKBENCH_PORT:'47942'},stdio:['ignore','pipe','pipe']});let serverLog='';server.stdout.on('data',d=>serverLog+=d);server.stderr.on('data',d=>serverLog+=d);for(let i=0;i<30;i++){try{await fetch('http://127.0.0.1:47942/__health');break}catch{await new Promise(r=>setTimeout(r,100))}}save('server-start.txt',serverLog);
browser=await chromium.launch({channel:'msedge',headless:true});const context=await browser.newContext({viewport:{width:1440,height:1000},recordHar:{path:path.join(out,'network.har')}});await context.tracing.start({screenshots:true,snapshots:true,sources:false});
await context.route('**/*',r=>{requests.push({url:r.request().url(),method:r.request().method()});return new URL(r.request().url()).hostname==='127.0.0.1'?r.continue():r.abort()});page=await context.newPage();page.setDefaultTimeout(12000);await page.goto('http://127.0.0.1:47942/');await page.locator('.job-title').first().waitFor();const initial=await page.locator('#result-count').innerText();
await page.locator('#search').fill('QA不存在的岗位-20261010');await page.locator('#search-form button').click();await page.waitForTimeout(80);check('L01-search-empty-is-empty',await page.locator('.job-title').count()===0,{result:await page.locator('#result-count').innerText(),initial,evidence:['L01-empty.png']});await screenshot('L01-empty');await page.locator('#reset-filters').click();
await page.locator('[name=currency]').selectOption('USD');await page.locator('[name=period]').selectOption('year');await page.locator('[name=salaryMin]').fill('150000');await page.locator('[name=salaryMax]').fill('200000');await page.getByRole('button',{name:'应用筛选',exact:true}).click();await page.waitForTimeout(80);const dataset=JSON.parse(fs.readFileSync(path.join(source,'public/data/jobs.json')));const expected=dataset.jobs.filter(j=>j.sourceStatus==='listed'&&j.salary.ranges.some(r=>r.currency==='USD'&&r.period==='year'&&r.kind==='salary'&&r.min<=200000&&r.max>=150000)).length;const displayed=await page.locator('#result-count').innerText();check('L02-salary-filter',parseInt(displayed.replace(/[^0-9]/g,''),10)===expected,{expected,displayed,evidence:['L02-salary.png']});await screenshot('L02-salary');
await page.locator('#save-search').click();await page.locator('#action-input').fill('独立验收薪资条件');await page.locator('#action-confirm').click();await page.locator('.job-title').first().click();const title=await page.locator('#detail-content h2').innerText();await page.locator('label').filter({has:page.locator('#detail-saved')}).click();await page.locator('#detail-stage').selectOption({label:'已投递'});await page.locator('#detail-tags').fill('独立验收，虚构标记');await page.locator('#detail-note').fill('仅独立验收用本机备注，不含真实个人资料');await page.getByRole('button',{name:'保存本机记录',exact:true}).click();await page.reload();await page.locator('[data-view=saved]').click();await page.locator('.job-title').first().waitFor();await page.locator('.job-title').first().click();check('L03-favorite-stage-tags-persist',await page.locator('#detail-content h2').innerText()===title&&await page.locator('#detail-stage').inputValue()==='已投递'&&(await page.locator('#detail-tags').inputValue()).includes('独立验收'),{title,evidence:['L03-persist.png']});await screenshot('L03-persist');await page.getByRole('button',{name:'关闭职位详情'}).click();
const local=await page.evaluate(()=>Object.fromEntries(Object.entries(localStorage)));save('workbench-storage-fictional.json',local);check('L04-notes-storage-boundary',JSON.stringify(local).includes('仅独立验收用本机备注'),{meaning:'Observed privacy boundary: job notes and tags are plaintext locally; resume vault encryption is separate.'});await page.locator('[data-view=local]').click();const event=page.waitForEvent('download');await page.getByRole('button',{name:'导出我的备份',exact:true}).click();const dl=await event;const backup=path.join(out,'fictional-job-record-backup.json');await dl.saveAs(backup);const backupData=JSON.parse(fs.readFileSync(backup));check('L05-backup-export',Object.values(backupData.records||{}).some(r=>r.title===title&&r.tags.includes('独立验收'))&&backupData.savedSearches.some(s=>s.name==='独立验收薪资条件'),{evidence:['fictional-job-record-backup.json']});
const fresh=await browser.newContext({viewport:{width:1440,height:1000}});await fresh.route('**/*',r=>new URL(r.request().url()).hostname==='127.0.0.1'?r.continue():r.abort());const oldPage=page;page=await fresh.newPage();await page.goto('http://127.0.0.1:47942/');await page.locator('.job-title').first().waitFor();await page.locator('[data-view=local]').click();await page.locator('#import-file').setInputFiles(backup);await page.locator('#action-confirm').click();await page.locator('[data-view=saved]').click();await page.locator('.job-title').first().waitFor();check('L06-backup-import-in-fresh-context',await page.locator('.job-title').first().innerText()===title,{title,evidence:['L06-import.png']});await screenshot('L06-import');await fresh.close();page=oldPage;
await page.locator('[data-view=jobs]').click();await page.getByRole('button',{name:'↳ 独立验收薪资条件',exact:true}).click();check('L07-saved-filter-reuse',await page.locator('[name=currency]').inputValue()==='USD'&&await page.locator('[name=salaryMin]').inputValue()==='150000',{evidence:['L07-reuse.png']});await screenshot('L07-reuse');await context.tracing.stop({path:path.join(out,'trace.zip')});await context.close();
}catch(e){fatal=e.stack;console.error(fatal);save('infrastructure-error.txt',fatal);if(page)await screenshot('interrupted').catch(()=>{});}finally{if(browser)await browser.close();if(server)server.kill();save('requests.json',requests);const counts={pass:results.filter(r=>r.status==='PASS').length,fail:results.filter(r=>r.status==='FAIL').length,skip:0};save('results.json',{run,source,counts,fatal,cases:results});console.log(JSON.stringify({counts,fatal:!!fatal}));if(fatal)process.exitCode=2;}})();


